param([string]$ConfigPath = "$PSScriptRoot\config.json")
Set-StrictMode -Version Latest
$ErrorActionPreference='Stop'
$cfg=Get-Content -Raw -LiteralPath $ConfigPath|ConvertFrom-Json
$repo=[string]$cfg.repo_root
$q=Join-Path $repo 'remote_bridge_queue'
$inbox=Join-Path $q 'jobs\inbox'
$outbox=Join-Path $q 'jobs\outbox'
$art=Join-Path $q 'artifacts'
New-Item -ItemType Directory -Force -Path $inbox,$outbox,$art|Out-Null
function Log($m){Add-Content -LiteralPath ([string]$cfg.log_file) -Value ("[$((Get-Date).ToString('o'))] "+$m) -Encoding UTF8}
function Git([string[]]$a){Push-Location $repo;try{$o=& git @a 2>&1|Out-String;if($LASTEXITCODE-ne0){throw $o};$o}finally{Pop-Location}}
function AllowedPath([string]$p){$f=[IO.Path]::GetFullPath([Environment]::ExpandEnvironmentVariables($p));foreach($d in $cfg.denied_paths){if($f-match$d){throw "blocked path: $f"}};$ok=$false;foreach($r in $cfg.allowed_roots){$rr=[IO.Path]::GetFullPath([Environment]::ExpandEnvironmentVariables([string]$r)).TrimEnd('\');if($f.StartsWith($rr,[StringComparison]::OrdinalIgnoreCase)){$ok=$true;break}};if(-not$ok){throw "outside allowed roots: $f"};$f}
function CommandAllowed([string]$c){foreach($d in $cfg.denied_commands){if($c-match$d){return $false}};return $true}
function Screenshot([string]$file){Add-Type -AssemblyName System.Windows.Forms;Add-Type -AssemblyName System.Drawing;$b=[Windows.Forms.SystemInformation]::VirtualScreen;$bmp=New-Object Drawing.Bitmap $b.Width,$b.Height;$g=[Drawing.Graphics]::FromImage($bmp);try{$g.CopyFromScreen($b.Left,$b.Top,0,0,$b.Size);$bmp.Save($file,[Drawing.Imaging.ImageFormat]::Png)}finally{$g.Dispose();$bmp.Dispose()}}
function Native{if(-not('BGRemote.Native'-as[type])){Add-Type @"
using System;using System.Runtime.InteropServices;namespace BGRemote{public static class Native{[DllImport("user32.dll")]public static extern bool SetCursorPos(int X,int Y);[DllImport("user32.dll")]public static extern void mouse_event(uint f,uint dx,uint dy,uint data,UIntPtr extra);[DllImport("user32.dll")]public static extern bool SetForegroundWindow(IntPtr h);}}
"@}}
function Click([int]$x,[int]$y){Native;[BGRemote.Native]::SetCursorPos($x,$y)|Out-Null;Start-Sleep -Milliseconds 60;[BGRemote.Native]::mouse_event(2,0,0,0,[UIntPtr]::Zero);[BGRemote.Native]::mouse_event(4,0,0,0,[UIntPtr]::Zero)}
function PasteText([string]$t){Add-Type -AssemblyName System.Windows.Forms;[Windows.Forms.Clipboard]::SetText($t);[Windows.Forms.SendKeys]::SendWait('^v')}
function SendKeys([string]$k){Add-Type -AssemblyName System.Windows.Forms;[Windows.Forms.SendKeys]::SendWait($k)}
function Focus([string]$rx){Native;$p=Get-Process|Where-Object{$_.MainWindowHandle-ne0-and$_.MainWindowTitle-match$rx}|Select-Object -First 1;if(-not$p){throw 'window not found'};[BGRemote.Native]::SetForegroundWindow($p.MainWindowHandle)|Out-Null;$p.MainWindowTitle}
function Artifact([string]$p){[ordered]@{path=[IO.Path]::GetRelativePath($repo,$p).Replace('\','/');sha256=(Get-FileHash -Algorithm SHA256 -LiteralPath $p).Hash;bytes=(Get-Item $p).Length}}
function RunJob($j){$id=[string]$j.id;if($id-notmatch'^[A-Za-z0-9._-]{1,100}$'){throw'bad id'};$ad=Join-Path $art $id;New-Item -ItemType Directory -Force -Path $ad|Out-Null;$r=[ordered]@{id=$id;action=[string]$j.action;ok=$false;device=$env:COMPUTERNAME;user=$env:USERNAME;started_at=(Get-Date).ToString('o');finished_at=$null;exit_code=0;stdout='';stderr='';artifacts=@()};try{switch([string]$j.action){'ping'{$r.stdout='pong'}'screenshot'{$f=Join-Path $ad 'desktop.png';Screenshot $f;$r.artifacts+=Artifact $f}'click'{Click ([int]$j.args.x) ([int]$j.args.y)}'type_text'{PasteText ([string]$j.args.text)}'keypress'{SendKeys ([string]$j.args.keys)}'window_list'{$r.stdout=(Get-Process|Where-Object{$_.MainWindowHandle-ne0-and$_.MainWindowTitle}|Select-Object Id,ProcessName,MainWindowTitle|ConvertTo-Json -Depth 4)}'focus_window'{$r.stdout=Focus ([string]$j.args.title_regex)}'list_dir'{$p=AllowedPath([string]$j.args.path);$r.stdout=(Get-ChildItem -Force -LiteralPath $p|Select-Object Name,FullName,Length,LastWriteTime,Mode|ConvertTo-Json -Depth 4)}'read_file'{$p=AllowedPath([string]$j.args.path);$m=if($j.args.max_bytes){[int]$j.args.max_bytes}else{300000};if((Get-Item $p).Length-gt$m){throw'file too large'};$r.stdout=[IO.File]::ReadAllText($p)}'write_text'{$p=AllowedPath([string]$j.args.path);$par=Split-Path -Parent $p;if($par){New-Item -ItemType Directory -Force -Path $par|Out-Null};[IO.File]::WriteAllText($p,[string]$j.args.content,(New-Object Text.UTF8Encoding($false)))}'hash'{$p=AllowedPath([string]$j.args.path);$r.stdout=(Get-FileHash -Algorithm SHA256 -LiteralPath $p).Hash}'adb'{$args=@();if($j.args.serial){$args+=@('-s',[string]$j.args.serial)};foreach($a in $j.args.arguments){$args+=[string]$a};$o=& adb @args 2>&1|Out-String;$r.exit_code=$LASTEXITCODE;$r.stdout=$o;if($LASTEXITCODE-ne0){throw'adb failed'}}'android_screenshot'{$serial=if($j.args.serial){[string]$j.args.serial}else{''};$f=Join-Path $ad 'android.png';$pi=New-Object Diagnostics.ProcessStartInfo;$pi.FileName='adb.exe';$pi.UseShellExecute=$false;$pi.RedirectStandardOutput=$true;$pi.RedirectStandardError=$true;$pi.CreateNoWindow=$true;$pi.Arguments=if($serial){"-s $serial exec-out screencap -p"}else{'exec-out screencap -p'};$p=New-Object Diagnostics.Process;$p.StartInfo=$pi;[void]$p.Start();$fs=[IO.File]::Open($f,[IO.FileMode]::Create,[IO.FileAccess]::Write);try{$p.StandardOutput.BaseStream.CopyTo($fs)}finally{$fs.Dispose()};$er=$p.StandardError.ReadToEnd();$p.WaitForExit();if($p.ExitCode-ne0){throw$er};$r.artifacts+=Artifact $f}'powershell'{$c=[string]$j.args.command;if(-not(CommandAllowed $c)){throw'command blocked'};$wd=if($j.args.working_dir){AllowedPath([string]$j.args.working_dir)}else{'E:\'};$enc=[Convert]::ToBase64String([Text.Encoding]::Unicode.GetBytes($c));Push-Location $wd;try{$o=& powershell.exe -NoProfile -NonInteractive -ExecutionPolicy Bypass -EncodedCommand $enc 2>&1|Out-String;$r.exit_code=$LASTEXITCODE;$r.stdout=$o;if($LASTEXITCODE-ne0){throw'PowerShell failed'}}finally{Pop-Location}}default{throw'unsupported action'}};$r.ok=$true}catch{$r.ok=$false;if($r.exit_code-eq0){$r.exit_code=1};$r.stderr=$_.Exception.Message}finally{$r.finished_at=(Get-Date).ToString('o')};[pscustomobject]$r}
$mx=New-Object Threading.Mutex($false,'Global\BlackGoldRemoteBridgeV11');if(-not$mx.WaitOne(0)){exit}
try{while($true){if(Test-Path([string]$cfg.disabled_flag)){Start-Sleep -Seconds([int]$cfg.poll_seconds);continue};try{$st=Push-Location $repo;try{& git status --porcelain 2>&1|Out-String}finally{Pop-Location};if(-not$st.Trim()){Git @('pull','--rebase','origin',[string]$cfg.branch)|Out-Null};$did=$false;foreach($jf in(Get-ChildItem -LiteralPath $inbox -Filter '*.json' -File|Sort-Object Name)){$j=Get-Content -Raw -LiteralPath $jf.FullName|ConvertFrom-Json;$out=Join-Path $outbox($j.id+'.json');if(Test-Path $out){continue};Log("job $($j.id) $($j.action)");RunJob $j|ConvertTo-Json -Depth 12|Set-Content -LiteralPath $out -Encoding UTF8;$did=$true};if($did){Git @('add','remote_bridge_queue/jobs/outbox','remote_bridge_queue/artifacts')|Out-Null;Push-Location $repo;try{& git commit -m ('remote bridge results '+(Get-Date -Format yyyyMMdd-HHmmss)) 2>&1|Out-Null;if($LASTEXITCODE-eq0){for($i=0;$i-lt4;$i++){& git push origin ([string]$cfg.branch) 2>&1|Out-Null;if($LASTEXITCODE-eq0){break};& git pull --rebase origin ([string]$cfg.branch) 2>&1|Out-Null;Start-Sleep 2}}}finally{Pop-Location}}}catch{Log $_.Exception.Message};Start-Sleep -Seconds([int]$cfg.poll_seconds)}}finally{try{$mx.ReleaseMutex()}catch{};$mx.Dispose()}